package net.civeira.phylax.feature.observe.observedsource.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ScrapeUrlVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property scrape url of observed source ")
  void test_scrape_url_v_o_builder() {
    Assertions.assertFalse(ScrapeUrlVO.nullValue().getScrapeUrl().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ScrapeUrlVO.tryFrom(null).getScrapeUrl().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ScrapeUrlVO.from("one").getScrapeUrl().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ScrapeUrlVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ScrapeUrlVO.from("one").toString());
  }
}
